const defaultUserCheckerStatus: UserCheckerStatusEntry = {
  label: '',
  icon: InfoIcon,
  variant: 'default',
  title: '',
  description: '',
};

export function getUserCheckerStatus(status: CheckrSummaryStatus): UserCheckerStatusEntry {
  return userCheckerStatuses[status] ?? { ...defaultUserCheckerStatus, label: snakeCaseToCapitalizedCase(status) };
}

export const checkrStatusSelectItems: SelectItem<CheckrSummaryStatus>[] = Object.entries(userCheckerStatuses).map(
  ([value, { label }]) => ({
    value: value as CheckrSummaryStatus,
    name: label,
  })
);

// Mirrors backend CheckrSummaryStatus.trigger() + .intermediate() — a manual re-trigger is
// blocked while the candidate is in any of these states (server enforces this with 409).
export const checkrInFlightStatuses: CheckrSummaryStatus[] = [
  'check_requested',
  'invitation_was_send',
  'report_pending',
  'candidate_action_required',
  'report_clear',
  'report_review_required',
  'report_pre_adverse',
  'report_dispute',
];
