import type { UserSimilarityCheckStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface UserSimilarityCheckStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const userSimilarityCheckStatuses: Record<UserSimilarityCheckStatus, UserSimilarityCheckStatusEntry> = {
  not_requested: { variant: 'default', label: 'Not Requested' },
  requested: { variant: 'info', label: 'Requested' },
  clear: { variant: 'success', label: 'Clear' },
  not_clear: { variant: 'destructive', label: 'Not Clear' },
};

const defaultUserSimilarityCheckStatus: UserSimilarityCheckStatusEntry = { label: '', variant: 'default' };

export function getUserSimilarityCheckStatus(status: UserSimilarityCheckStatus): UserSimilarityCheckStatusEntry {
  return (
    userSimilarityCheckStatuses[status] ?? {
      ...defaultUserSimilarityCheckStatus,
      label: snakeCaseToCapitalizedCase(status),
    }
  );
}

export const similarityCheckStatusSelectItems: SelectItem<UserSimilarityCheckStatus>[] = Object.entries(
  userSimilarityCheckStatuses
).map(([value, { label }]) => ({
  value: value as UserSimilarityCheckStatus,
  name: label,
}));
