import type { RegisteredParty } from '~/client';

interface RegisteredPartyEntry {
  name: string;
}

export const registeredParties: Record<RegisteredParty, RegisteredPartyEntry> = {
  republican: { name: 'Republican' },
  democratic: { name: 'Democratic' },
  undecided: { name: 'Undecided' },
  unknown: { name: 'Unknown' },
};

export function getRegisteredParty(party: RegisteredParty): RegisteredPartyEntry {
  return registeredParties[party] ?? { name: snakeCaseToCapitalizedCase(party) };
}

export const registeredPartiesItems: SelectItem<RegisteredParty>[] = Object.entries(registeredParties).map(
  ([value, { name }]) => ({
    value: value as RegisteredParty,
    name,
  })
);
